/** Stamped in by `define` in vite.config.ts; see buildInfo() there. */
declare const __BUILD__: {
  /** Short git hash, with a trailing `+` when built with uncommitted changes. Null if git was unavailable. */
  commit: string | null;
  /** ISO 8601: the commit's date, or the build time when there is no commit. */
  at: string;
};
